using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CharactersList", menuName = "Data/Characters/Characters List")]
public class CharactersList : ScriptableObject
{
	[Header("Characters")]
	public Character[] charactersList;

	public Character GetCharacter(string characterName)
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (charactersList[i].name == characterName)
			{
				return charactersList[i];
			}
		}
		return null;
	}

	public void LockAllCharacters()
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum)
			{
				charactersList[i].CharacterProgression.CharacterUnlocked = false;
			}
		}
	}

	public void ToggleAllCharactersAstreaHeartReached(bool value)
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum)
			{
				charactersList[i].CharacterProgression.AstreaHeartReached = value;
			}
		}
	}

	public bool AllCharactersReachedAstreaHeart()
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum && !charactersList[i].CharacterProgression.AstreaHeartReached)
			{
				return false;
			}
		}
		return true;
	}

	public bool AtLeastOneCharactersReachedAstreaHeart()
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum && charactersList[i].CharacterProgression.AstreaHeartReached)
			{
				return true;
			}
		}
		return false;
	}

	public bool AllCharactersButOrionAndCurrentCharacterReachedAstreaHeart(Character orionCharacter, Character currentCharacter)
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			Character character = charactersList[i];
			if (!character.CharacterEnum && character != orionCharacter && character != currentCharacter && !character.CharacterProgression.AstreaHeartReached)
			{
				return false;
			}
		}
		return true;
	}

	public bool AllCharactersButOrionReachedAstreaHeart(Character orionCharacter)
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum && !charactersList[i].CharacterProgression.AstreaHeartReached && charactersList[i] != orionCharacter)
			{
				return false;
			}
		}
		return true;
	}

	public bool NoCharactersReachedAstreaHeart()
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum && charactersList[i].CharacterProgression.AstreaHeartReached)
			{
				return false;
			}
		}
		return true;
	}

	public bool AllCharactersOnMaxLevel()
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum && charactersList[i].GetCharacterLevel() < 6)
			{
				return false;
			}
		}
		return true;
	}

	public bool AllCharactersDefeatedAstrea()
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum && !charactersList[i].CharacterAchievement.HeroAchievementData.IsUnlocked())
			{
				return false;
			}
		}
		return true;
	}

	public bool AllCharactersButCurrentDefeatedMaxNonHiddenAnomalyAndAstreaDefeatedAtTheSameTime(Character currentCharacter)
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum && charactersList[i] != currentCharacter && !charactersList[i].CharacterProgression.MaxNonHiddenAnomalyAndAstreaDefeatedAtTheSameTime)
			{
				return false;
			}
		}
		return true;
	}

	public void SetAllCharactersCurrentAndUnlockedAstreaLevel(int level)
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum)
			{
				charactersList[i].CharacterProgression.CurrentAstreaLevel = level;
				charactersList[i].CharacterProgression.UnlockedAstreaLevel = level;
			}
		}
	}

	public void IncreaseAllCharactersUnlockedAnomalyLevelAndAstreaLevel()
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum)
			{
				charactersList[i].CharacterProgression.UnlockedAnomalyLevel++;
				charactersList[i].CharacterProgression.UnlockedAstreaLevel++;
			}
		}
	}

	public void ResetToZeroAllCharacterXP()
	{
		for (int i = 0; i < charactersList.Length; i++)
		{
			if (!charactersList[i].CharacterEnum)
			{
				charactersList[i].CharacterProgression.CharacterXP = 0;
			}
		}
	}
}
